const $=id=>document.getElementById(id),KEY='ui-alchemist-bloom-v1',query=new URLSearchParams(location.search),previewKey=query.get('preview'),demo=WORLDS.some(w=>w.key===previewKey)||previewKey==='systems';
const LABELS={border:['枠線','生成ボタンに枠線をつけます。'],color:['色','生成ボタンと部品の色を作ります。'],font:['フォント','画面で使う文字を読みやすくします。'],shadow:['影','ボタンに立体感を加えます。'],motion:['アニメーション','カーソルが自動でボタンを押す動きを作ります。'],window:['生成アプリ','生成元と部品の作成機能を、一つのアプリにまとめます。'],slider:['生成リズム','手動操作と自動生成の配分を切り替えます。'],gauge:['蓄積ゲージ','生産を蓄え、20秒ごとに追加で払い出します。'],corners:['角丸','操作部品の輪郭を整えます。'],tabs:['Canvas','生成アプリを元に、写真と文字を配置するデザインアプリを作ります。'],break:['デスクトップ','今のアプリをウィンドウに収め、写真壁紙とファイルを置くデスクトップを作ります。'],wallpaper:['ファイル管理','制作フォルダーから文書や画像を開けるようにします。'],dock:['タスクバー','アプリの最小化と再表示、バックグラウンド生成を管理します。'],atelier:['作業スペース','今のデスクトップを残して、複数の作業スペースを管理します。'],gradient:['別の作業スペース','資料用と自動処理用のスペースを追加します。'],glass:['半透明の素材','タスクバーと操作パネルに背景が透ける素材を使います。'],light:['ウィンドウの描画','重なったウィンドウの影と輪郭を整えます。'],blueprint:['環境マネージャー','作ったスペースを一つの環境として収め、複数の仮想環境を管理します。'],palette:['配色ライブラリ','制作アプリで使える配色を増やします。'],material:['システムテーマ','管理画面の色と操作部品を統一します。'],constellation:['バックグラウンド描画','表示中の環境と背景の描画を並行して実行します。'],harmony:['共通コンポーネント','作った部品をすべての環境で再利用します。'],workspaces:['ネットワークデスクトップ','今の環境マネージャーを収めた、新しい夜景のデスクトップを作ります。'],launchpad:['アプリランチャー','環境管理、ファイル、部品ライブラリをタスクバーから開けるようにします。'],network:['セッション管理','複数のローカル環境の接続状態を一画面で管理します。'],panorama:['統合管理の準備','作った環境の一覧と操作機能をまとめます。'],ecosystem:['環境の統合管理','今のPC環境を含む、すべての作業環境を一画面で管理します。']};
for(const r of RECIPES){[r.name,r.desc]=LABELS[r.id];const special={border:'クリック +1',color:'クリック ×2 / 自動生成 ×2',font:'クリック +2',motion:'自動生成 ×2',gauge:'20秒ごとに生産10秒分を追加',atelier:'追加生産 +80%',ecosystem:'生産 ×2.5'};r.effect=special[r.id]||(['window','break','blueprint','harmony','workspaces','launchpad','network','panorama'].includes(r.id)?'生産 ×2':'生産 ×1.5')}
let saveOK=true,toastTimer,lastTime=performance.now(),saveAt=0,transitioning=false,previewObservers=[],soundContext,dragState=null;
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw))}catch{saveOK=false}
const DEFAULT_NOTE='制作ノート\n\n・海岸の写真を使ってポスターを作る\n・文字のサイズと余白を調整する\n・次は作業スペースを増やす\n';
state.notes=typeof state.notes==='string'?state.notes.slice(0,8000):DEFAULT_NOTE;
function sampleWorld(level){state={...fresh(),owned:RECIPES.slice(0,WORLDS[level].sample||WORLDS[level].count).map(r=>r.id),cursors:level?18:0,px:level?12480:0,total:level?180450:0,gauge:8,auto:false,notes:DEFAULT_NOTE};state.history=state.owned.slice(-7).map((id,i)=>({id,at:Date.now()-(7-i)*42000}));uiState={...uiState,view:null,partsOpen:[3,6].includes(level),canvasOpen:true,remoteOpen:true,filesOpen:false,managerOpen:false,activeHost:0}}
let away=0;if(demo){sampleWorld(WORLDS.findIndex(w=>w.key===(previewKey==='systems'?'os':previewKey)))}else{const t=Math.min(8*3600,Math.max(0,(Date.now()-state.saved)/1000));if(t>10){const previous=state.px;tick(t);away=state.px-previous}uiState.partsOpen=[3,6].includes(worldLevel())}
function currentLevel(){return uiState.view===null?worldLevel():uiState.view}
function save(){if(demo)return;state.saved=Date.now();try{localStorage.setItem(KEY,JSON.stringify(state));saveOK=true}catch{saveOK=false}$('save-status').textContent=saveOK?'保存済み':'保存できません';document.querySelectorAll('[data-save]').forEach(n=>n.textContent=saveOK?'保存済み':'保存できません')}
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3400)}
function sound(buy=false){if(!state.sound)return;try{soundContext??=new(window.AudioContext||window.webkitAudioContext)();soundContext.resume();const now=soundContext.currentTime;[buy?523:440,...(buy?[659]:[])].forEach((f,i)=>{const o=soundContext.createOscillator(),g=soundContext.createGain();o.frequency.value=f;o.type='sine';g.gain.setValueAtTime(.022,now+i*.06);g.gain.exponentialRampToValueAtTime(.001,now+i*.06+.17);o.connect(g).connect(soundContext.destination);o.start(now+i*.06);o.stop(now+i*.06+.19)})}catch{}}
function fitPreviews(){previewObservers.forEach(o=>o.disconnect());previewObservers=[];document.querySelectorAll('.preview-frame').forEach(frame=>{const child=frame.firstElementChild;if(!child)return;const fit=()=>{const s=Math.min(frame.clientWidth/1280,frame.clientHeight/800);child.style.transform=`scale(${s})`;child.style.left=(frame.clientWidth-1280*s)/2+'px';child.style.top=(frame.clientHeight-800*s)/2+'px'};fit();const observer=new ResizeObserver(fit);observer.observe(frame);previewObservers.push(observer)})}
function render(animate=false,previousLevel=null){
 const old=$('computer').firstElementChild,oldRect=old?.getBoundingClientRect(),copy=animate?old?.cloneNode(true):null;
 document.body.className=['border','color','font','shadow','motion','glass','light'].filter(has).map(x=>'has-'+x).join(' ');
 const level=currentLevel();$('computer').innerHTML=screen(level,{showControls:state.total>0||demo});
 if(uiState.filesOpen&&![3,6,7].includes(level))$('computer').firstElementChild.insertAdjacentHTML('beforeend',filesWindow());
 document.querySelectorAll('[data-window-id]').forEach(el=>{const id=el.dataset.windowId;if(uiState.focus===id&&!el.closest('[inert]'))el.style.zIndex='18';if(uiState[id+'Max'])el.classList.add('maximized');const pos=uiState.positions?.[level+':'+id];if(pos&&!el.closest('[inert]')){el.style.left=Math.min(pos.x,innerWidth-120)+'px';el.style.top=Math.min(pos.y,innerHeight-100)+'px';el.style.right='auto'}});
 document.querySelectorAll('.artboard-copy').forEach(n=>n.classList.toggle('text-selected',uiState.layer==='title'));fitPreviews();update();$('preview-select').value=String(worldLevel());
 if(copy&&oldRect&&level===previousLevel+1&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const target=$('computer').querySelector(`.preview-frame[data-level="${previousLevel}"]`)||(level===3?$('computer').querySelector('.desktop-app'):null);if(target){const box=target.getBoundingClientRect(),ghost=document.createElement('div');ghost.className='transition-copy';ghost.inert=true;ghost.setAttribute('aria-hidden','true');Object.assign(ghost.style,{left:oldRect.x+'px',top:oldRect.y+'px',width:oldRect.width+'px',height:oldRect.height+'px'});copy.style.width=oldRect.width+'px';copy.style.height=oldRect.height+'px';ghost.append(copy);document.body.append(ghost);transitioning=true;const duration=1500;ghost.animate([{left:oldRect.x+'px',top:oldRect.y+'px',width:oldRect.width+'px',height:oldRect.height+'px'},{left:box.x+'px',top:box.y+'px',width:box.width+'px',height:box.height+'px'}],{duration,easing:'cubic-bezier(.22,.8,.2,1)',fill:'forwards'});copy.animate([{transform:'scale(1)'},{transform:`scale(${box.width/oldRect.width})`}],{duration,easing:'cubic-bezier(.22,.8,.2,1)',fill:'forwards'});$('computer').firstElementChild.animate([{opacity:0},{opacity:1}],{duration:1050});setTimeout(()=>{ghost.remove();transitioning=false;update()},duration+40)}}
}
function update(){
 document.querySelectorAll('[data-value]').forEach(n=>{const key=n.dataset.value;n.textContent=key==='balance'?number(state.px):key==='rate'?number(rate())+' px / 秒':key==='cursor'?state.cursors+' 個':key==='gauge'?Math.floor(state.gauge/20*100)+'%':''});
 const r=nextRecipe();document.querySelectorAll('[data-purchase]').forEach(b=>b.disabled=!r||state.px<r.cost||transitioning);document.querySelectorAll('[data-price-progress]').forEach(n=>n.style.width=r?Math.min(100,state.px/r.cost*100)+'%':'100%');document.querySelectorAll('[data-price-wait]').forEach(n=>{if(!r){n.textContent='';return}const remaining=Math.max(0,r.cost-state.px),seconds=remaining/Math.max(1,rate()*(has('gauge')?1.5:1));n.textContent=remaining===0?'作成できます':rate()>0?(seconds<60?'自動生成で約 '+Math.ceil(seconds)+' 秒':'自動生成で約 '+Math.ceil(seconds/60)+' 分'):'あと '+number(remaining)+' px'});
 document.querySelectorAll('[data-cursor-buy]').forEach(b=>{b.disabled=state.px<cursorCost()||state.cursors>=300||!has('border');if(currentLevel()!==0)b.textContent=state.cursors>=300?'上限に達しました':number(cursorCost())+' px で追加'});document.querySelectorAll('[data-gauge]').forEach(n=>n.style.width=state.gauge/20*100+'%');
 const now=new Date(),clock=new Intl.DateTimeFormat('ja-JP',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Tokyo'}).format(now),date=new Intl.DateTimeFormat('ja-JP',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Asia/Tokyo'}).format(now);document.querySelectorAll('[data-clock]').forEach(n=>n.textContent=clock);document.querySelectorAll('[data-date]').forEach(n=>n.textContent=date);
}
function generate(event){const started=state.total>0,v=clickPower();earn(v);state.clicks++;sound();if(!started)render();else update();if(has('motion')&&event&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const f=document.createElement('span');f.className='floating-pixel';f.textContent='+'+number(v);f.style.left=(event.clientX||innerWidth/2)+'px';f.style.top=(event.clientY||innerHeight/2)+'px';document.body.append(f);setTimeout(()=>f.remove(),950)}}
function purchase(){if(transitioning)return;const r=nextRecipe(),before=worldLevel();if(!r||!buyRecipe(r.id))return;uiState.view=null;if(worldLevel()!==before){uiState.partsOpen=[3,6].includes(worldLevel());uiState.filesOpen=false;uiState.activeHost=0;uiState.positions={}}sound(true);render(worldLevel()!==before,before);save();if(worldLevel()===before)notify(r.name+'を作成しました');if(r.id==='ecosystem')notify('すべての環境を構築しました')}
function openSettings(){$('sound-setting').checked=state.sound;$('auto-setting').checked=state.auto;$('auto-setting').disabled=!has('blueprint');$('save-status').textContent=demo?'プレビューは保存されません':saveOK?'このブラウザに保存':'保存できません';$('settings').showModal()}
function openFile(title,kind){$('file-title').textContent=title;const body=$('file-content');body.replaceChildren();if(kind==='note'){const area=document.createElement('textarea');area.className='note-editor';area.setAttribute('aria-label','制作ノート');area.value=state.notes||DEFAULT_NOTE;area.maxLength=8000;area.oninput=()=>{state.notes=area.value;save()};body.append(area)}else if(kind==='photo'){const img=document.createElement('img');img.className='file-image';img.src='./assets/wallpaper-coast.png';img.alt='海岸の風景';body.append(img);const p=document.createElement('p');p.className='file-description';p.textContent='coastline.png / PNG画像';body.append(p)}else{const history=document.createElement('div');history.className='events-list';history.innerHTML=activity(27);body.append(history);const title=document.createElement('p');title.textContent='作成した画面を見る';body.append(title);WORLDS.forEach(w=>{if(demo||state.owned.length>=w.count){const a=document.createElement('a');a.className='text-button';a.style.display='block';a.href='?preview='+w.key;a.textContent=w.name+' →';body.append(a)}})}$('file-viewer').showModal()}
function doAction(action,button,event){
 if(action==='generate')generate(event);
 else if(action==='purchase')purchase();
 else if(action==='cursor'){if(buyCursor()){sound();render();save()}}
 else if(action==='settings')openSettings();
 else if(action==='close-dialog')button.closest('dialog').close();
 else if(action==='toggle-parts'){uiState.partsOpen=!(uiState.partsOpen&&uiState.focus==='parts');uiState.focus='parts';if(currentLevel()===2){uiState.partsOpen=true;notify('右の部品一覧から作成できます')}render()}
 else if(action==='files'){uiState.filesOpen=!(uiState.filesOpen&&uiState.focus==='files');uiState.focus='files';render()}
 else if(action==='note')openFile('制作ノート.txt','note');
 else if(action==='photo')openFile('coastline.png','photo');
 else if(action==='history')openFile('作成の履歴','history');
 else if(action==='design'){state.design=(state.design+1)%2;render();save()}
 else if(action==='tool'){uiState.tool=button.dataset.tool;if(uiState.tool==='type')uiState.layer='title';if(uiState.tool==='image')uiState.layer='photo';render()}
 else if(action==='layer'){uiState.layer=button.dataset.layer;render()}
 else if(action==='show-layers'){uiState.layer=uiState.layer==='photo'?'title':'photo';render();notify('選択レイヤー：'+(uiState.layer==='photo'?'写真':'タイトル'))}
 else if(action==='zoom'){uiState.zoom=uiState.zoom===50?75:50;render()}
 else if(action==='rhythm'){state.rhythm=(state.rhythm+1)%3;render();save()}
 else if(action==='auto-toggle'){if(!has('blueprint'))return;state.auto=!state.auto;save();notify('カーソルの自動購入：'+(state.auto?'有効':'無効'))}
 else if(action==='host'){uiState.activeHost=Number(button.dataset.host);render()}
 else if(action==='minimize'){const win=button.dataset.window;if(win==='canvas')uiState.canvasOpen=false;else if(win==='remote')uiState.remoteOpen=false;else if(win==='parts')uiState.partsOpen=false;else if(win==='files')uiState.filesOpen=false;else if(win==='manager')uiState.managerOpen=false;render()}
 else if(action==='maximize'){const win=button.dataset.window;uiState[win+'Max']=!uiState[win+'Max'];render()}
 else if(action==='open-canvas'){uiState.canvasOpen=true;uiState.focus='canvas';render()}
 else if(action==='open-remote'){uiState.remoteOpen=true;uiState.focus='remote';render()}
 else if(action==='spaces'){if(!has('atelier')){notify('作業スペースは、部品一覧から作成できます');return}uiState.view=currentLevel()===4?null:4;uiState.partsOpen=false;render()}
 else if(action==='enter-desktop'){uiState.view=3;uiState.partsOpen=true;render()}
 else if(action==='enter-network'){uiState.view=6;uiState.partsOpen=true;render()}
 else if(action==='enter-manager'){uiState.view=5;uiState.activeHost=0;render()}
 else if(action==='connect-host'){uiState.view=uiState.activeHost===2?1:uiState.activeHost===1?3:4;uiState.partsOpen=false;render()}
 else if(action==='engine'){uiState.view=1;render()}
 else if(action==='manager'){uiState.managerOpen=!uiState.managerOpen;render()}
 else if(action==='return'){uiState.view=null;uiState.managerOpen=false;uiState.partsOpen=[3,6].includes(worldLevel());render()}
 else if(action==='preview-controls'){if(demo)$('preview-controls').hidden=!$('preview-controls').hidden;else openFile('成長の記録','history')}
 else if(action==='fullscreen'){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.().catch(()=>notify('この画面では全画面表示を利用できません'));else document.exitFullscreen?.();$('settings').close()}
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-act]');if(!button||button.closest('[inert]'))return;doAction(button.dataset.act,button,event)});
$('computer').addEventListener('pointerdown',event=>{const bar=event.target.closest('[data-drag]');if(!bar||event.target.closest('button')||bar.closest('[inert]')||event.button!==0)return;const win=bar.closest('[data-window-id]');if(!win||win.classList.contains('maximized'))return;const box=win.getBoundingClientRect();dragState={id:bar.dataset.drag,win,bar,startX:event.clientX,startY:event.clientY,left:box.left,top:box.top};bar.setPointerCapture(event.pointerId);event.preventDefault()});
$('computer').addEventListener('pointermove',event=>{if(!dragState)return;const d=dragState,x=Math.max(-d.win.offsetWidth+130,Math.min(innerWidth-130,d.left+event.clientX-d.startX)),y=Math.max(0,Math.min(innerHeight-90,d.top+event.clientY-d.startY));Object.assign(d.win.style,{left:x+'px',top:y+'px',right:'auto'});uiState.positions??={};uiState.positions[currentLevel()+':'+d.id]={x,y}});
document.addEventListener('pointerup',()=>dragState=null);
$('computer').addEventListener('pointerdown',event=>{const win=event.target.closest('[data-window-id]');if(!win||win.closest('[inert]'))return;uiState.focus=win.dataset.windowId;document.querySelectorAll('[data-window-id]').forEach(other=>{if(!other.closest('[inert]'))other.style.zIndex=other===win?'18':''})});
document.addEventListener('pointercancel',()=>dragState=null);
$('sound-setting').onchange=e=>{state.sound=e.target.checked;sound(true);save()};$('auto-setting').onchange=e=>{state.auto=e.target.checked;save()};
$('export-save').onclick=()=>{save();const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='ui-alchemist-world.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('import-save').onclick=()=>$('save-file').click();$('save-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const imported=validate(JSON.parse(await file.text()));if(!confirm('現在の進行を、読み込んだセーブで置き換えますか？'))return;state=imported;state.notes=typeof state.notes==='string'?state.notes.slice(0,8000):DEFAULT_NOTE;state.saved=Date.now();uiState.view=null;render();save();notify('セーブを読み込みました')}catch{notify('セーブを読み込めませんでした')}finally{e.target.value=''}};
$('reset').onclick=()=>{if(!confirm('現在の進行を消して、最初のボタンに戻りますか？'))return;state=fresh();state.notes=DEFAULT_NOTE;uiState.view=null;$('settings').close();render();save()};
function switchPreview(level){if(transitioning||level<0||level>=WORLDS.length)return;const before=worldLevel();sampleWorld(level);history.replaceState(null,'','?preview='+WORLDS[level].key);render(level===before+1,before);$('preview-controls').hidden=false}
$('preview-select').innerHTML=WORLDS.map((w,i)=>`<option value="${i}">${i}. ${w.name}</option>`).join('');$('preview-select').onchange=e=>switchPreview(Number(e.target.value));$('preview-next').onclick=()=>switchPreview(Math.min(WORLDS.length-1,worldLevel()+1));
let hiddenAt=0;document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAt=Date.now();save()}else{if(hiddenAt&&!demo){const previous=state.px;tick(Math.min(8*3600,Math.max(0,(Date.now()-hiddenAt)/1000)));if(state.px-previous>1)notify('不在中に '+number(state.px-previous)+' px を生成しました');hiddenAt=0}lastTime=performance.now();update()}});window.addEventListener('pagehide',save);
setInterval(()=>{if(document.hidden)return;const now=performance.now();if(!demo)tick(Math.min(5,(now-lastTime)/1000));lastTime=now;update();if(now-saveAt>5000){saveAt=now;save()}},180);
render();if(demo)$('preview-controls').hidden=false;if(away>1)setTimeout(()=>notify('不在中に '+number(away)+' px を生成しました'),500);if(!saveOK)setTimeout(()=>notify('保存を読み込めませんでした。設定からデータを書き出せます。'),900);

